PRINT N'--- db/seed/0105_role_alias.sql';
EXEC (N'/* =====================================================================
   0105_role_alias.sql
   Loads     : route role names that the client file does not define (working assumption WA-02)
   Source    : derived from the responsible / accountable roles of the REF-46 sheet "Approval Routes" [REF-46:L0210-L0223]
   Writes to : app.role_alias
   Database  : the ATLAS Fabric SQL database (item of type SQL database)
   Re-runnable: yes (see the notes below)
   Existing rows with the same key are updated to the values below; missing rows are added;
   nothing is deleted.

   GENERATED by tools/gen_ref46_seed.py from REF-46_ATLAS_Security_Routing_and_Business_Rule_Intake.txt.
   Do not edit by hand: change the generator and run it again.
   Contains no person''s e-mail address (those go only in db/seed/local/).
   ===================================================================== */
SET NOCOUNT ON;

IF CAST(SERVERPROPERTY(''EngineEdition'') AS int) = 11
   OR @@VERSION LIKE N''%Data Warehouse%''
   OR DB_NAME() NOT LIKE N''ATLAS[_]SQL[_]DB%''
BEGIN
    PRINT ''FAIL 0105.0 wrong editor: connected to "'' + DB_NAME() + ''" on engine '' + ISNULL(CAST(SERVERPROPERTY(''EngineEdition'') AS varchar(20)), ''?'') + '' (11 = the warehouse-style engine, which the SQL analytics endpoint uses). Open the item named ATLAS_SQL_DB whose type is SQL database and run this from New query there. Nothing was changed.'';
    RETURN;
END
IF OBJECT_ID(N''app.role_alias'', N''U'') IS NULL
BEGIN
    PRINT ''FAIL 0105.1 table app.role_alias not found: run migration 0003_security.sql first. Nothing was changed.'';
    RETURN;
END

BEGIN TRY
    DECLARE @src TABLE
    (
        alias_name nvarchar(64) NOT NULL PRIMARY KEY,
        role_name nvarchar(64) NOT NULL,
        is_assumption bit NOT NULL,
        related_question nvarchar(40) NULL,
        note nvarchar(400) NULL
    );
    INSERT INTO @src (alias_name, role_name, is_assumption, related_question, note) VALUES
        (N''Operations-IOC - NMD'', N''Operations-IOC'', 1, N''Q-496'', N''Working assumption WA-02 [INFERRED]: the client file uses "Operations-IOC - NMD" in approval routes (responsible on R2 [REF-46:L0211]; responsible on R3 [REF-46:L0212]; responsible on R4 [REF-46:L0213]; responsible on R5 [REF-46:L0214]) but defines no such role in Role Definitions; read as "Operations-IOC". Awaiting the client answer to Q-496.'');   -- 4 uses in routes, first R2 [REF-46:L0211]

    DECLARE @n_updated int = 0, @n_new int = 0, @n_source int = (SELECT COUNT(*) FROM @src);

    BEGIN TRANSACTION;
    UPDATE t SET
            t.role_name = s.role_name,
            t.is_assumption = s.is_assumption,
            t.related_question = s.related_question,
            t.note = s.note
    FROM app.role_alias AS t
    JOIN @src AS s ON s.alias_name = t.alias_name
    WHERE EXISTS (SELECT s.role_name, s.is_assumption, s.related_question, s.note EXCEPT SELECT t.role_name, t.is_assumption, t.related_question, t.note);
    SET @n_updated = @@ROWCOUNT;

    INSERT INTO app.role_alias (alias_name, role_name, is_assumption, related_question, note)
    SELECT s.alias_name, s.role_name, s.is_assumption, s.related_question, s.note
    FROM @src AS s
    WHERE NOT EXISTS (SELECT 1 FROM app.role_alias AS t WHERE t.alias_name = s.alias_name);
    SET @n_new = @@ROWCOUNT;
    COMMIT TRANSACTION;

    PRINT ''OK  0105 loaded: '' + CAST(@n_source AS varchar(12)) + '' aliases ('' + CAST(@n_new AS varchar(12)) + '' new, '' + CAST(@n_updated AS varchar(12)) + '' updated)'';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    PRINT ''FAIL 0105.9 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;
');

